            self.advance()
            result = self.expr()
            if self.current_char == ')':
                self.advance()
            else:
                self.error()
            return result
        elif self.current_char.isdigit() or self.current_char == '.':
            return self.number()
        self.error()

    def term(self):
        result = self.factor()
        while self.current_char is not None and self.current_char in '*/':
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
